import { HTMLAttributes, Ref, forwardRef } from 'react';

interface Props extends HTMLAttributes<HTMLDialogElement> {
    open?: boolean;
}

const Dialog = forwardRef<HTMLDialogElement, Props>((props, ref): JSX.Element => {
    const supportsDialog =
        typeof HTMLDialogElement !== 'undefined' &&
        typeof HTMLDialogElement.prototype.showModal === 'function' &&
        typeof HTMLDialogElement.prototype.close === 'function';

    if (supportsDialog) {
        return <dialog {...props} ref={ref} />;
    }

    const { open, hidden, ...rest } = props;

    return (
        <div
            role="dialog"
            {...(rest as unknown as HTMLAttributes<HTMLDivElement>)}
            hidden={hidden || !open}
            ref={ref as Ref<HTMLDivElement>}
        />
    );
});

Dialog.displayName = 'Dialog';

export default Dialog;

import { createRef } from 'react';

import { render } from '@testing-library/react';

import Dialog from './Dialog';

describe('Dialog', () => {
    it('forwards attributes and the ref to a supported native dialog', () => {
        const prototype = HTMLDialogElement.prototype;
        const showModal = Object.getOwnPropertyDescriptor(prototype, 'showModal');
        const close = Object.getOwnPropertyDescriptor(prototype, 'close');
        Object.defineProperty(prototype, 'showModal', { configurable: true, value: jest.fn() });
        Object.defineProperty(prototype, 'close', { configurable: true, value: jest.fn() });

        try {
            const ref = createRef<HTMLDialogElement>();
            const { getByRole } = render(
                <Dialog ref={ref} open aria-label="Native example" data-testid="native-host">
                    <button type="button">Hello</button>
                </Dialog>
            );

            const host = getByRole('dialog', { name: 'Native example' });
            expect(host.tagName).toBe('DIALOG');
            expect(host).toHaveAttribute('open');
            expect(host).toHaveAttribute('data-testid', 'native-host');
            expect(ref.current).toBe(host);
            expect(getByRole('button', { name: 'Hello' })).toBeVisible();
        } finally {
            if (showModal) {
                Object.defineProperty(prototype, 'showModal', showModal);
            } else {
                Reflect.deleteProperty(prototype, 'showModal');
            }
            if (close) {
                Object.defineProperty(prototype, 'close', close);
            } else {
                Reflect.deleteProperty(prototype, 'close');
            }
        }
    });

    it('uses an accessible fallback when dialog methods are unavailable', () => {
        const ref = createRef<HTMLDialogElement>();
        const { getByRole } = render(
            <Dialog ref={ref} open aria-label="Example" data-testid="host" className="example">
                <button type="button">Hello</button>
            </Dialog>
        );

        const host = getByRole('dialog', { name: 'Example' });
        expect(host.tagName).toBe('DIV');
        expect(host).toHaveAttribute('data-testid', 'host');
        expect(host).toHaveClass('example');
        expect(ref.current).toBe(host);
        expect(getByRole('button', { name: 'Hello' })).toBeVisible();
    });
});
import { ElementType, createContext, useLayoutEffect, useRef, useState } from 'react';

import useInstance from '@proton/hooks/useInstance';
import usePrevious from '@proton/hooks/usePrevious';
import { modalTwoRootClassName } from '@proton/shared/lib/busy';

import { classnames, generateUID } from '../../helpers';
import { Box, PolymorphicComponentProps } from '../../helpers/react-polymorphic-box';
import { useHotkeys } from '../../hooks';
import Dialog from '../dialog/Dialog';
import { useFocusTrap } from '../focus';
import { Portal } from '../portal';
import { useModalPosition } from './modalPositions';

import './Modal.scss';

export type ModalSize = 'small' | 'medium' | 'large' | 'full';

/**
 * Omission of id from ModalOwnProps because in ModalOwnProps "id"
 * is optional, whereas in ModalContextValue it is guaranteed.
 * Same for size.
 */
type ModalContextValue = ModalOwnProps & { id: string; size: ModalSize };

export const ModalContext = createContext({} as ModalContextValue);

export interface ModalOwnProps {
    /**
     * Whether the modal is open or not.
     */
    open?: boolean;
    size?: ModalSize;
    fullscreenOnMobile?: boolean;
    fullscreen?: boolean;
    /**
     * Disables closing the modal by pressing the 'Escape' key.
     */
    disableCloseOnEscape?: boolean;
    /**
     * Optional id to overwrite the internally generated id, which
     * is used for accessibility purposes (e.g.aria-labelledby & id
     * of the Title in ModalHeader)
     */
    id?: string;
    /**
     * Fires when the user clicks on the close button or when he
     * presses the escape key, unless 'disableCloseOnEscape' is
     * set to true.
     */
    onClose?: () => void;
    /**
     * Fires when the Modal has finished its exit animation.
     */
    onExit?: () => void;
}

enum ExitState {
    idle,
    exiting,
    exited,
}

const defaultElement = 'div';

export type ModalProps<E extends ElementType = typeof defaultElement> = PolymorphicComponentProps<E, ModalOwnProps>;

const Modal = <E extends ElementType = typeof defaultElement>({
    open,
    size = 'medium',
    fullscreenOnMobile,
    fullscreen,
    onClose,
    onExit,
    disableCloseOnEscape,
    className,
    ...rest
}: PolymorphicComponentProps<E, ModalOwnProps>) => {
    const [exit, setExit] = useState(() => (open ? ExitState.idle : ExitState.exited));
    const id = useInstance(() => generateUID('modal'));
    const dialogRef = useRef(null);

    const active = exit !== ExitState.exited;
    const last = useModalPosition(active || false);

    const focusTrapProps = useFocusTrap({
        active,
        rootRef: dialogRef,
    });

    const modalContextValue: ModalContextValue = {
        id,
        open,
        size,
        onClose,
        disableCloseOnEscape,
    };

    const previousOpen = usePrevious(open);

    useLayoutEffect(() => {
        if (!previousOpen && open) {
            setExit(ExitState.idle);
        } else if (previousOpen && !open) {
            setExit(ExitState.exiting);
        }
    }, [previousOpen, open]);

    useHotkeys(
        dialogRef,
        [
            [
                'Escape',
                (e) => {
                    if (!active || disableCloseOnEscape) {
                        return;
                    }
                    e.stopPropagation();
                    onClose?.();
                },
            ],
        ],
        { dependencies: [active, disableCloseOnEscape] }
    );

    if (!active) {
        return null;
    }

    const exiting = exit === ExitState.exiting;

    return (
        <Portal>
            <div
                className={classnames([
                    modalTwoRootClassName,
                    exiting && 'modal-two--out',
                    fullscreenOnMobile && 'modal-two--fullscreen-on-mobile',
                    fullscreen && 'modal-two--fullscreen',
                    !last && 'modal-two--is-behind-backdrop',
                ])}
                onAnimationEnd={({ animationName }) => {
                    if (exiting && animationName === 'anime-modal-two-out') {
                        setExit(ExitState.exited);
                        onExit?.();
                    }
                }}
            >
                <Dialog
                    ref={dialogRef}
                    open={active}
                    aria-labelledby={id}
                    aria-describedby={`${id}-description`}
                    {...focusTrapProps}
                    className={classnames([
                        'modal-two-dialog outline-none',
                        className,
                        size === 'small' && 'modal-two-dialog--small',
                        size === 'large' && 'modal-two-dialog--large',
                        size === 'full' && 'modal-two-dialog--full',
                    ])}
                >
                    <ModalContext.Provider value={modalContextValue}>
                        <Box as={defaultElement} className="modal-two-dialog-container" {...rest} />
                    </ModalContext.Provider>
                </Dialog>
            </div>
        </Portal>
    );
};

export default Modal;
